{
  "contract": "SummoningOfTheWicked",
  "closure": {
    "site_function": "openPortalSealed",
    "site_call": ".call",
    "functions": [
      "openPortalSealed"
    ],
    "justification": "The function `openPortalSealed` contains a low-level `.call` which allows re-entrancy. The exposed storage variables are 'demons', 'offering', and 'portal'. The closure includes only `openPortalSealed` because it is the function that directly involves the risky external call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "openPortalSealed"
    ],
    "nesting_bound": {
      "openPortalSealed": 1
    }
  },
  "phases": {
    "function": "openPortalSealed",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Number of demons affected during the callback window in `openPortalSealed`.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "demons == demons + inFlight",
    "stable_formula": "demons == demons",
    "kind": "additive"
  },
  "composition": {
    "target_property": "demons == demons",
    "rule": "During the callback window of `openPortalSealed`, the invariant `demons == demons + inFlight` must hold, ensuring correct accounting across re-entrancy."
  }
}
